import{bV as i,aL as a,u as e,G as r}from"./chunks/framework.BfzMay2U.js";const b=JSON.parse('{"title":"如何准备面试","description":"","frontmatter":{"title":"如何准备面试","date":"2026-09-19T23:38:01.000Z"},"headers":[],"relativePath":"java/interview.md","filePath":"java/interview.md"}'),o={name:"java/interview.md"};function u(t,l,h,n,d,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="如何留下好映像" tabindex="-1">如何留下好映像 <a class="header-anchor" href="#如何留下好映像" aria-label="Permalink to &quot;如何留下好映像&quot;">​</a></h1><ul><li>确保不会流行坏映像</li><li>注意面试礼仪</li><li>让面试官感觉到你和其他候选人的区别</li></ul><h2 id="面试礼仪" tabindex="-1">面试礼仪 <a class="header-anchor" href="#面试礼仪" aria-label="Permalink to &quot;面试礼仪&quot;">​</a></h2><ul><li>守时，预留半小时，如果无法避免，提前沟通</li><li>见面问好，离开道谢</li><li>多用礼貌用语：请，谢谢</li><li>主动破冰，自我介绍要有亮点</li><li>避免刻意讨好的拍马屁</li><li>不要过分展示自己，过于夸大</li></ul><h2 id="事实和观点的区别" tabindex="-1">事实和观点的区别 <a class="header-anchor" href="#事实和观点的区别" aria-label="Permalink to &quot;事实和观点的区别&quot;">​</a></h2><blockquote><p>当时我遇到了一个技术难题，xxx (描述具体遇到的问题)，当时小组有 2 位同事先后尝试去解决这个问题，花了一段时间没有明显的进展。然后我主动去了解了这个问题，查看了相关源码，定位到了具体的问题，发现是 xxx 原因导致的，然后对这个问题进行了修复。</p></blockquote><p>当时项目遇到了一个技术难题，xxx，当时团队里没人能搞定这个问题，最终是我定位到问题并修复的。【夸大】</p><h2 id="体现你的不同" tabindex="-1">体现你的不同 <a class="header-anchor" href="#体现你的不同" aria-label="Permalink to &quot;体现你的不同&quot;">​</a></h2><ul><li>精心准备面试</li><li>突出自己的特点【技术上、项目上，解决了某个难度的问题，或者开源项目】，面试前深入的准备</li><li>表达对细分行业或者企业的喜欢</li></ul><blockquote><p>了解到贵公司是做 xxx 的，我对这方面很感兴趣，希望有机会在这个行业发展</p></blockquote><p>【需要提前了解这个行业的知识，面试官可能会让你谈谈企业的文化或价值观】</p><h2 id="冰山模型" tabindex="-1">冰山模型 <a class="header-anchor" href="#冰山模型" aria-label="Permalink to &quot;冰山模型&quot;">​</a></h2><h3 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h3><p><img src="https://virusoss.oss-cn-shanghai.aliyuncs.com/image-20260919234922106.png" alt="image-20260919234922106" loading="lazy"></p><p>冰山以上的素质</p><ul><li>知识</li><li>技能</li></ul><p>冰山以下的素质</p><ul><li>价值观，两难问题的立场来判断</li><li>社会角色，自我形象和自我认知</li><li>个性，个人的思维方式，做事的风格，性格，适应能力</li><li>动机，个人对特定领域的想法</li></ul><p>面试的阶段考察的素质不同</p><ul><li>一面主要考察候选人能不能干活，也就是对知识和技能的考察</li><li>二面主要考察的是候选人是不是可培养，着重考察候选人的潜力</li><li>三面主要考察候选人的价值观，看候选人能干多久</li></ul><h3 id="对于求职者的意义" tabindex="-1">对于求职者的意义 <a class="header-anchor" href="#对于求职者的意义" aria-label="Permalink to &quot;对于求职者的意义&quot;">​</a></h3><ul><li>明确非技术类问题的出题方向和意图</li><li>重视冰山以下的部分的能力展示</li></ul><h3 id="如何应对冰山以下的问题" tabindex="-1">如何应对冰山以下的问题 <a class="header-anchor" href="#如何应对冰山以下的问题" aria-label="Permalink to &quot;如何应对冰山以下的问题&quot;">​</a></h3><ul><li>价值观方面：组织利益要优先于个人利益；长期利益要优先于短期利益，在不影响企业需求的情况下兼容个人需求</li><li>自我形象和认知层面：需要表现出愿意学习，愿意探索未知的领域，把失败当做经历而非结果。</li><li>个性方面：表现出自己的适应能力，能调整自己的风格，更快的适应团队</li><li>动机方面：尽可能表现出对企业和业务的兴趣和对技术的追求</li></ul><h2 id="面试秘笈" tabindex="-1">面试秘笈 <a class="header-anchor" href="#面试秘笈" aria-label="Permalink to &quot;面试秘笈&quot;">​</a></h2><ul><li>面试前：投入最多精力的地方，主动去总结 <ul><li>精心制作简历，并选择合适的投递渠道 <ul><li>各大招聘网站 ，拉钩，boss 直聘</li><li>公司网站</li><li>线下招聘会</li><li>社交平台，公司的微博或公众号</li><li>猎头【说明企业对人才的需求较大】</li><li>内推 <strong>优先考虑内推</strong></li></ul></li><li><strong>参加面试前，详细了解企业的情况</strong><ul><li>企业基本信息，所属的行业，发展前景，行业中的位置</li><li>创始人的背景</li><li>企业的核心产品，盈利情况</li><li>企业的价值观使命和愿景</li><li>你面试的部门对企业的价值或者企业里的地位</li><li>企业认为我的哪些方面比较适合这个岗位</li><li>项目组人数，主要业务，技术栈，团队技术氛围咋样</li><li>直接汇报的对象的岗位</li></ul></li><li>做好充分的面试准备 <ul><li>面试开始前的准备 <ul><li>着装得体</li><li>保持微笑和良好的心理状态</li><li>充分休息，带上打印好的简历</li></ul></li><li>技术面试的准备，投入最多精力的 <ul><li>简历上出现的知识点一定要准备扎实，进行系统的梳理</li><li>准备好项目相关的面试问题和答案</li><li>算法面试</li><li>介绍你最近/最有成就感/最困难的项目</li><li>介绍下你处理过的最难的技术问题</li><li>介绍一个你犯过的技术问题或者造成的故障</li><li>根据 star 提问法，针对每个项目提问以及答案</li><li>展示自己在项目中的重要性 <ul><li>针对复杂需求设计了什么方案，难点是什么？怎么解决的 ？</li><li>项目最终达到什么样的成果？自己发挥着什么样的角色？</li><li>项目完成后你总结了什么经验？有哪些不足？有什么改进方案？</li><li>养成整理和记录的习惯</li><li>找那些能让自己简历有亮点的工作</li></ul></li></ul></li><li>非技术面试的准备 <ul><li>根据岗位要求准备自我介绍【面试的第一阶段】 <ul><li>精心准备、按需调整、表现<strong>匹配度</strong>和<strong>亮点</strong></li><li>表达对行业，企业，业务或技术的兴趣</li><li>自我介绍控制在 2 到 3 分钟，简历上有的东西要简化或一笔带过</li></ul></li><li>提前准备冰山以下部分的面试题</li></ul></li></ul></li><li>多进行模拟面试 <ul><li>多面试找状态</li><li>多面试找不足</li><li>可以自己找朋友充当面试官，或者找镜子</li></ul></li><li>注意行为细节，避免扣印象分，紧张的时候会有小动作</li><li>注意沟通效率，结果先行</li><li>向面试官提问要恰当 <ul><li>询问一些关于团队或项目，以及网上获取不到的信息</li></ul></li></ul></li><li>面试中 <ul><li>避免挤牙膏式的问题</li><li>需要自己要问什么，以及问什么合适</li></ul></li><li>面试后 <ul><li>总结和复习</li><li>对没回答出来的面试题进行补救</li></ul></li></ul><h2 id="简历的针对性" tabindex="-1">简历的针对性 <a class="header-anchor" href="#简历的针对性" aria-label="Permalink to &quot;简历的针对性&quot;">​</a></h2><h3 id="技能的针对性" tabindex="-1">技能的针对性 <a class="header-anchor" href="#技能的针对性" aria-label="Permalink to &quot;技能的针对性&quot;">​</a></h3><ul><li>通过招聘企业的岗位描述信息获取</li><li>直接咨询企业</li><li>咨询企业内部的员工或者猎头</li></ul><h3 id="业务背景的针对性" tabindex="-1">业务背景的针对性 <a class="header-anchor" href="#业务背景的针对性" aria-label="Permalink to &quot;业务背景的针对性&quot;">​</a></h3><ul><li>突出与企业岗位相似的业务经验</li></ul><h3 id="价值观的一致性" tabindex="-1">价值观的一致性 <a class="header-anchor" href="#价值观的一致性" aria-label="Permalink to &quot;价值观的一致性&quot;">​</a></h3><ul><li>在简历的个人评价中可适当加一些符合企业价值观的特质，准备匹配这些特质的事，至少准备一件事来说明你有这个特质</li></ul><h2 id="大厂眼中的好简历" tabindex="-1">大厂眼中的好简历 <a class="header-anchor" href="#大厂眼中的好简历" aria-label="Permalink to &quot;大厂眼中的好简历&quot;">​</a></h2><h3 id="标准的简历结构" tabindex="-1">标准的简历结构 <a class="header-anchor" href="#标准的简历结构" aria-label="Permalink to &quot;标准的简历结构&quot;">​</a></h3><ul><li>基本信息 <ul><li>姓名</li><li>手机号</li><li>邮箱</li><li>年龄</li><li>求职意向</li><li>期望工作地点</li></ul></li><li>教育经历 <ul><li>大学及以上的学历</li><li>包括学校名称、专业，以及起止时间</li><li>如果学历不好，可以放到后面，个人评价之前</li></ul></li><li>专业技能 <ul><li>技能点+掌握程度【精通、熟悉、掌握、了解】</li><li>技术栈【有实际项目经验的编程语言】</li><li>业务能力</li><li>软技能【学习能力、管理能力等】</li><li>给面试官出题范围，将面试官引导到自己熟悉的领域，但是自己熟悉的领域你也要提前熟悉了解</li><li>这里的技能点一定是深入掌握的，最好是看过源码的</li><li>突出你与职位的匹配度</li></ul></li><li>实习/工作经历 <ul><li>实习/工作的企业，在企业的工作的起始时间以及成功</li><li>按照时间倒序展示</li></ul></li><li>科研/项目经历 <ul><li>参加的项目介绍，项目的起止时间，主要职责</li><li>遇到的挑战以及产出的成果</li><li>使用时间倒序展示</li><li>在xxx情况或 xxx 背景下，为了解决 xxx 问题或者达到 xxx目标</li><li>我通过 xxx 方法或者技术最终获得了 xxx 成功，最好量化的指标，突出项目成功</li></ul></li><li>个人评价 <ul><li>专业特长、性格、做事风格</li></ul></li><li>技能证书/获奖经历（非必须） <ul><li>专业证书或者外语证书</li><li>大厂的项目大奖</li><li>一般放到个人评价之前</li></ul></li></ul><h2 id="简历优化的建议" tabindex="-1">简历优化的建议 <a class="header-anchor" href="#简历优化的建议" aria-label="Permalink to &quot;简历优化的建议&quot;">​</a></h2><ul><li>慎用精通</li><li>突出个人亮点，如何发现项目的问题，以及如何解决的，项目的架构选型，为什么这么选，与其他的相比有什么优势</li><li>确保简历上的每个技术点你都有比较系统的了解</li></ul><h2 id="体现亮点" tabindex="-1">体现亮点 <a class="header-anchor" href="#体现亮点" aria-label="Permalink to &quot;体现亮点&quot;">​</a></h2><ul><li>“亮点”是经历出来的，比如大厂的实习经历、参与开源项目</li><li>不是没有“亮点”，而是缺少发现亮点的眼睛，需要在项目开发过程中养成记录的习惯，解决的一些疑难问题，可以总结成技术文档</li><li>某行业某业务有深入的理解</li><li>在项目中解决的一些难点</li></ul><h2 id="简历长度" tabindex="-1">简历长度 <a class="header-anchor" href="#简历长度" aria-label="Permalink to &quot;简历长度&quot;">​</a></h2><ul><li>应届生一页，社招 2 页，最长不要超过 3 页</li><li>太长说明你没有认真做取舍和总结</li><li>不要使用双面打印</li></ul><h3 id="排版工整" tabindex="-1">排版工整 <a class="header-anchor" href="#排版工整" aria-label="Permalink to &quot;排版工整&quot;">​</a></h3><ul><li>以可读性为主，电子版简历最好是 pdf 格式</li><li>模版：<a href="https://gitee.com/phper95/go-interview/tree/master/%E7%AE%80%E5%8E%86%E6%A8%A1%E6%9D%BF" target="_blank" rel="noreferrer">https://gitee.com/phper95/go-interview/tree/master/%E7%AE%80%E5%8E%86%E6%A8%A1%E6%9D%BF</a> 仅提供排版学习</li></ul><h2 id="电话面试回复" tabindex="-1">电话面试回复 <a class="header-anchor" href="#电话面试回复" aria-label="Permalink to &quot;电话面试回复&quot;">​</a></h2><ul><li>养成一个礼貌性接电话的习惯：“您好，请问您是？”</li><li>可以预约时间再进行面试，电话面试前你需要一个准备工作，周围环境不方便面试，预约到次日可以给自己一些准备时间</li><li>克服紧张情绪</li><li>面试官提问的时候，你可以复述面试官的问题跟面试官确认</li><li>在电话面试过程中我们需要保持微笑，不要打断面试官讲话</li></ul><h2 id="给-hr-留下好印象的方法" tabindex="-1">给 HR 留下好印象的方法 <a class="header-anchor" href="#给-hr-留下好印象的方法" aria-label="Permalink to &quot;给 HR 留下好印象的方法&quot;">​</a></h2><ul><li>先确保不做减法再做加法 <ul><li>守时，早到 15 分钟为最佳</li><li>穿着得体，看上去干净利索，面试前，嚼口香糖，面试的时候吐掉</li></ul></li><li>注意自己的沟通表达能力，吐字清晰，可以提前准备问题，提前想好问题，如果表达能力较弱，要刻意练习。结论先行+三点论，不断调整自己的说话的语气。</li><li>表达对面试官的感谢和对岗位的热情。</li></ul><h2 id="hr-的提问的问题" tabindex="-1">HR 的提问的问题 <a class="header-anchor" href="#hr-的提问的问题" aria-label="Permalink to &quot;HR 的提问的问题&quot;">​</a></h2><ol><li>你为什么离职？ <ol><li>不要说裁员</li><li>可以写个人原因离职</li><li>自己对某方面的业务领域感兴趣，由于公司战略层面调整，原有的业务线公司不再投入，了解到贵公司主要是做某某业务，使用了某某技术领域，所以决定到贵公司发展。</li></ol></li><li>谈谈你对加班的看法？【态度和责任心的表达】 <ol><li>如果是工作需要我，我会加班，加上我现在单身，没有家庭负担，可以全身心投入工作，同时我也会提高工作效率，减少不必要的加班。</li></ol></li><li>你最大的缺点是什么？【不要把优点包装成缺点】 <ol><li>有时候不好意思拒绝同事的求助，尽可能的揽下，有时候会影响自己的工作进度；通过任务的优先级设置优先顺序，以该优先顺序向求助的同事展示自己手上的工作。</li></ol></li><li>你最大的优点是什么？【自我反省和自我认知的能力，看你简历的是否真实】 <ol><li>最好能拿出证明你优点的事情</li></ol></li><li>你还有什么问题要问的？ <ol><li>问公司的竞争制度、有哪些培训可以参加</li><li>企业制度、岗位以及个人成长相关的问题</li></ol></li><li>如果工作一段时间后发现这个岗位不适合你，你会怎么办？ <ol><li>自己认可也希望在这发展，先从自身找原因 <ol><li>如果是效率跟不上，分析这些任务没有按期交付的原因；是不是你自己的方法错了，或者是对工作的理解出现了问题，如果是理解不到位，那就加强沟通，了解这个任务的目的以及领导到底要什么而尽快做出调整；如果是做事的方法有问题，则需要向做的好的同事虚心请教，如果实在不适合这个岗位，需要及时和公司沟通看有没有合适的岗位，如果实在没有呢，需要办理好交接去找一个适合自己的职业和岗位。</li></ol></li></ol></li><li>如果由于你的工作失误而给公司带来了损失，你会怎么办？【考察责任心和担当】 <ol><li>第一时间及时响应 ，先想办法解决问题，将事故的损失降到最低，事后再进行分析定位事故出现的原因，总结经验教训，并制定相应的策略，避免相关的事故再次发生。</li></ol></li><li>你对我们公司了解多少？ <ol><li>需要再面试前多做准备</li></ol></li><li>你为什么选择我们公司？ <ol><li>自己了解到贵公司各个行业上是领先的</li><li>对企业的某个技术领域非常感兴趣，希望再这个技术领域扎根</li><li>在为企业创造价值的同时，也为自己在这个行业走的更远</li></ol></li></ol><h2 id="如果表现出自己的沟通能力" tabindex="-1">如果表现出自己的沟通能力 <a class="header-anchor" href="#如果表现出自己的沟通能力" aria-label="Permalink to &quot;如果表现出自己的沟通能力&quot;">​</a></h2><ul><li>沟通的起点是倾听</li><li>避免挤牙膏式的问答</li><li>用自己的话复述一遍，确认你理解了面试官的问题</li><li>良好的表达能力是沟通能力的前提</li></ul><h3 id="如何提高" tabindex="-1">如何提高 <a class="header-anchor" href="#如何提高" aria-label="Permalink to &quot;如何提高&quot;">​</a></h3><ul><li>先意识到问题，然后进行刻意练习</li><li>理解能力很重要，学会换位思考</li></ul><h2 id="面试容易紧张怎么办" tabindex="-1">面试容易紧张怎么办？ <a class="header-anchor" href="#面试容易紧张怎么办" aria-label="Permalink to &quot;面试容易紧张怎么办？&quot;">​</a></h2><ul><li>换个思路看问题 <ul><li>面试对你来说意味着什么，其实是双向选择，看成是一次交流，一次是和企业合作交流</li><li>最坏的情况无非就是企业没有选择你，天不会塌下来，你也可以总结经验，你也只是暂时失去了机会</li><li>面试的过程也是一次锻炼，也能从这次面试里学到东西</li></ul></li><li>重复练习是克服紧张情绪的特效药</li><li>做好充分的准备，你的底气来自于你充分的准备 <ul><li>抬头挺胸：姿势效应</li></ul></li></ul><h2 id="你应该问面试官什么问题" tabindex="-1">你应该问面试官什么问题？ <a class="header-anchor" href="#你应该问面试官什么问题" aria-label="Permalink to &quot;你应该问面试官什么问题？&quot;">​</a></h2><h3 id="不适合问的问题【和技术面试官】" tabindex="-1">不适合问的问题【和技术面试官】 <a class="header-anchor" href="#不适合问的问题【和技术面试官】" aria-label="Permalink to &quot;不适合问的问题【和技术面试官】&quot;">​</a></h3><ul><li>询问薪资以及晋升涨薪制度【通常是和 HR 聊】</li><li>询问面试官结果和面试表现，会诱导面试官思考你的不足</li><li>跟面试和岗位毫无关系的问题</li></ul><h3 id="推荐问的问题" tabindex="-1">推荐问的问题 <a class="header-anchor" href="#推荐问的问题" aria-label="Permalink to &quot;推荐问的问题&quot;">​</a></h3><ul><li>团队的现状和需要解决的一些关键问题和调整</li><li>产品的业务是什么？核心竞争力？用到了哪些技术栈？</li><li>补充面试过程中没回答好的问题</li><li>面试官的微信【一些算法和编码当时没有思路，可以在面试结束后发给面试官】（暂时没有想到其他的问题了，能不能留个微信，如果有其他问题我们在微信沟通，顺便请教一些面试中的问题。）</li></ul><h2 id="职业规划" tabindex="-1">职业规划 <a class="header-anchor" href="#职业规划" aria-label="Permalink to &quot;职业规划&quot;">​</a></h2><blockquote><p>选择比努力重要</p></blockquote><ul><li>对面试官讲的职业规划 <ul><li>体现出你的上进心，对技术业务或者管理的追求</li></ul></li><li>自己的职业规划 <ul><li>技术人员的通常有哪些发展方向？ <ul><li>业务方向：产品经理和运营</li><li>技术方向：业务开发、技术专家、技术架构师、测试等</li><li>管理方向：项目管理，部门经理、CTO 等</li></ul></li><li>在职业发展的不同阶段我应该注重哪些方面的成长？ <ul><li>对自己能力的素质有清晰的认知</li><li>距离自己想要的还缺点什么</li><li>为了达到这样的水平，你应该做什么，我们需要分阶段的实现</li><li>初入职场1~3 年，探索期，需要多经历，去寻找适合自己的方向</li><li>3~5 年以技术能力的提升为主要目的，简历上要有亮点</li><li>5~10 年从更高的视角来看技术的能力，完成从术到道的转变</li></ul></li><li>什么时候应该“求”变，如何求变？ <ul><li>如果你负责的产品线已经不需要你付出多大努力的时候，公司不会投入过多的经历，你每天只需要随便处理，一旦产品下线，就会被淘汰，一旦到了瓶颈，就要求变</li><li>没事找事：需要一些有挑战性的工作</li><li>转岗：如果转岗还没有找到合适的事情，那就需要跳槽了</li><li>跳槽：优先考虑大厂，能在短时间内获取技术上的成长</li></ul></li></ul></li><li>喜欢和擅长应该优先考虑哪种工作？ <ul><li>先选择自己擅长的</li><li>别让自己做那些让自己讨厌的事情</li></ul></li></ul><h2 id="为什么基础类面试题是必问的" tabindex="-1">为什么基础类面试题是必问的？ <a class="header-anchor" href="#为什么基础类面试题是必问的" aria-label="Permalink to &quot;为什么基础类面试题是必问的？&quot;">​</a></h2><ul><li>面试是一个探寻候选人知识边界的过程</li><li>基础扎实的人能独挡一面</li><li>面试官对基础题的考察越来越灵活多变</li><li>重视对基础题的准备</li><li>对基础知识一定要有自己的理解，深挖细节</li><li>主动探索，构建更体系化的知识体系</li></ul><h2 id="怎么准备技术面试" tabindex="-1">怎么准备技术面试 <a class="header-anchor" href="#怎么准备技术面试" aria-label="Permalink to &quot;怎么准备技术面试&quot;">​</a></h2><ul><li>数据库和缓存【频率最高】 <ul><li>MySQL 和 redis</li><li>MongoDB，ElasticSearch</li></ul></li><li>数据结构和算法【大厂必备项】</li><li>操作系统和网络【linux 操作系统，CPU 和内存调度，IO模型，http 和 TCP】</li><li>编程语言层面的基础知识和一些特性</li><li>项目经历【频率第二高】，一定要准备自己熟悉的项目</li><li>针对自己薄弱点准备 <ul><li>将考点整理出思维导图并根据问题描述答案</li><li>一场技术面试后没回答上来的问题，需要完善和补充</li></ul></li><li>针对重点的考点准备 <ul><li>大部分公司都会问的知识点，MySQL、redis、数据结构和算法等</li><li>企业岗位职责和岗位要求中的提高的一些技术点</li><li>简历上提到的一些技能点</li></ul></li></ul><h2 id="如何回答基础类面试题打动面试官" tabindex="-1">如何回答基础类面试题打动面试官 <a class="header-anchor" href="#如何回答基础类面试题打动面试官" aria-label="Permalink to &quot;如何回答基础类面试题打动面试官&quot;">​</a></h2><ul><li>尽可能全面，尽可能给出多种解决方式</li><li>尽可能将原理关联到自己通过了解其中原理后是怎么运用起来的。</li><li>尽可能深入思考</li></ul>',70)])])}const q=i(o,[["render",u]]);export{b as __pageData,q as default};
